mapper.select:
SELECT

FROM shop_delivery d

    d.is_deleted = 0


        AND d.outbound_id = #{q.outboundId}



        AND (d.rider_id = #{q.scopeRiderId}
        OR (d.rider_id IS NULL AND d.status = 1))


        AND d.rider_id = #{q.riderId}


        AND d.delivery_type = #{q.deliveryType}


        AND d.status = #{q.status}



        AND d.accept_time >= #{q.acceptBeginTime}


        AND d.accept_time <= #{q.acceptEndTime}


        AND d.assign_time >= #{q.assignBeginTime}


        AND d.assign_time <= #{q.assignEndTime}



        AND (d.delivery_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR d.outbound_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR d.receiver_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR d.receiver_phone LIKE CONCAT('%', #{q.keyword}, '%'))



ORDER BY

    CASE WHEN d.sender_lng IS NULL OR d.sender_lat IS NULL THEN 1 ELSE 0 END,
    ST_Distance_Sphere(POINT(#{q.residentLng}, #{q.residentLat}), POINT(d.sender_lng, d.sender_lat)),

d.id DESC
